.ocf-page{max-width:1180px;margin:0 auto}
.ocf-card{overflow:visible;border:1px solid #e0e7f0;border-radius:16px;background:#fff;box-shadow:0 12px 34px rgba(16,38,79,.06)}
.ocf-card__head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:24px 26px;border-bottom:1px solid #e7edf5}
.ocf-card__head-main{display:flex;align-items:flex-start;gap:14px}
.ocf-card__icon{width:46px;height:46px;display:grid;place-items:center;flex:0 0 46px;border-radius:13px;background:#eef4ff;color:#164a8b}
.ocf-card__icon svg{width:22px;height:22px}
.ocf-card__head h2{margin:0;color:#10264f;font-size:20px;line-height:1.25}
.ocf-card__head p{max-width:760px;margin:6px 0 0;color:#6e7e95;font-size:13px;line-height:1.55}
.ocf-badge{display:inline-flex;align-items:center;gap:7px;min-height:30px;padding:0 11px;border-radius:999px;background:#fff3e9;color:#c65408;font-size:11px;font-weight:800;white-space:nowrap}
.ocf-body{padding:26px}
.ocf-errors{margin-bottom:22px;padding:15px 17px;border:1px solid #fecaca;border-radius:12px;background:#fff7f7;color:#991b1b}
.ocf-errors strong{display:block;font-size:13px}.ocf-errors ul{margin:8px 0 0;padding-left:20px;font-size:12px;line-height:1.6}
.ocf-section{padding:0}
.ocf-section__title{display:flex;align-items:flex-start;gap:12px;margin-bottom:21px}
.ocf-section__number{width:36px;height:36px;display:grid;place-items:center;flex:0 0 36px;border-radius:10px;background:#edf4ff;color:#174b8f;font-size:13px;font-weight:900}
.ocf-section__title h3{margin:0;color:#10264f;font-size:18px;line-height:1.25}
.ocf-section__title p{margin:5px 0 0;color:#75849a;font-size:12px;line-height:1.5}
.ocf-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 18px}
.ocf-grid--three{grid-template-columns:repeat(3,minmax(0,1fr))}
.ocf-span-2{grid-column:1/-1}
.ocf-field{display:flex;flex-direction:column;min-width:0}
.ocf-field>label,.ocf-fieldset>legend{display:block;margin:0 0 8px;color:#243f65;font-size:13px;font-weight:800;line-height:1.3}
.ocf-required{color:#dc2626}
.ocf-optional{color:#8996a9;font-size:11px;font-weight:600}
.ocf-field input:not([type="radio"]):not([type="checkbox"]),.ocf-field select,.ocf-field textarea,.ocf-select-button{width:100%;border:1px solid #ccd7e5;border-radius:10px;background:#fff;color:#17345f;font-size:14px;outline:none;transition:border-color .18s ease,box-shadow .18s ease,background .18s ease}
.ocf-field input:not([type="radio"]):not([type="checkbox"]),.ocf-field select,.ocf-select-button{height:50px;padding:0 14px}
.ocf-field textarea{min-height:120px;padding:13px 14px;resize:vertical;line-height:1.55}
.ocf-field input:focus,.ocf-field select:focus,.ocf-field textarea:focus,.ocf-select-button:focus{border-color:#f97316;box-shadow:0 0 0 4px rgba(249,115,22,.10)}
.ocf-field input::placeholder,.ocf-field textarea::placeholder{color:#a1acba}
.ocf-help{margin-top:7px;color:#7d899b;font-size:11px;line-height:1.45}
.ocf-error{margin-top:7px;color:#be123c;font-size:11px;line-height:1.4}
.ocf-phone{display:grid;grid-template-columns:120px minmax(0,1fr);gap:9px}
.ocf-password{position:relative}.ocf-password input{padding-right:50px!important}.ocf-password button{position:absolute;right:6px;top:6px;width:38px;height:38px;display:grid;place-items:center;border:0;border-radius:8px;background:#f1f5fa;color:#61728a;cursor:pointer}.ocf-password button:hover{background:#e8eef6;color:#174b8f}.ocf-password button svg{width:19px;height:19px}
.ocf-choice-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.ocf-choice{display:flex;align-items:flex-start;gap:11px;min-height:78px;padding:15px;border:1px solid #d6dfeb;border-radius:12px;background:#fff;cursor:pointer;transition:.18s ease}
.ocf-choice:hover{border-color:#b7c7da;background:#fbfdff}
.ocf-choice:has(input:checked){border-color:#f97316;background:#fff8f2;box-shadow:0 0 0 3px rgba(249,115,22,.08)}
.ocf-choice input{width:18px;height:18px;margin:2px 0 0;flex:0 0 18px;accent-color:#f97316}
.ocf-choice strong{display:block;color:#17345f;font-size:13px;line-height:1.35}.ocf-choice small{display:block;margin-top:4px;color:#74839a;font-size:11px;line-height:1.45}
.ocf-file{position:relative;padding:14px;border:1px dashed #b9c8da;border-radius:12px;background:#f9fbfe}
.ocf-file input[type=file]{width:100%;height:auto!important;padding:0!important;border:0!important;background:transparent!important;font-size:12px!important;box-shadow:none!important}
.ocf-file input[type=file]::file-selector-button{margin-right:12px;padding:10px 14px;border:0;border-radius:9px;background:#eaf1fb;color:#174b8f;font-size:12px;font-weight:800;cursor:pointer}
.ocf-file input[type=file]::file-selector-button:hover{background:#dfeaf8}
.ocf-subpanel{grid-column:1/-1;padding:19px;border:1px solid #dfe7f1;border-radius:13px;background:#f9fbfe}
.ocf-subpanel__head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:17px}.ocf-subpanel__head h4{margin:0;color:#17345f;font-size:15px}.ocf-subpanel__head span{color:#75849a;font-size:11px}
.ocf-hidden{display:none!important}
.ocf-category{position:relative}.ocf-select-button{position:relative;padding-right:43px;text-align:left;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ocf-select-button:after{content:'⌄';position:absolute;right:15px;top:10px;color:#61728a;font-size:20px}.ocf-category-menu{position:absolute;z-index:60;top:calc(100% + 7px);left:0;right:0;padding:10px;border:1px solid #d4deea;border-radius:12px;background:#fff;box-shadow:0 20px 50px rgba(16,38,79,.18)}.ocf-category-menu input{height:44px!important;margin-bottom:9px}.ocf-category-options{max-height:260px;overflow:auto}.ocf-category-option{display:block;width:100%;padding:11px 12px;border:0;border-radius:8px;background:#fff;color:#294364;text-align:left;font-size:12px;cursor:pointer}.ocf-category-option:hover{background:#eef4ff;color:#075ee8}
.ocf-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:25px;padding-top:21px;border-top:1px solid #e5ebf3}.ocf-actions__right{display:flex;gap:10px;margin-left:auto}.ocf-actions .btn{min-height:46px;padding:0 18px}
.ocf-wizard{overflow:hidden}
.ocf-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-bottom:1px solid #e2e9f2;background:#f8fafc}
.ocf-step{position:relative;display:flex;align-items:center;gap:10px;min-height:76px;padding:15px 18px;border:0;border-right:1px solid #e2e9f2;background:transparent;color:#6f7e94;text-align:left;cursor:pointer}.ocf-step:last-child{border-right:0}.ocf-step__dot{width:32px;height:32px;display:grid;place-items:center;flex:0 0 32px;border-radius:9px;background:#e8eef6;color:#54708f;font-size:12px;font-weight:900}.ocf-step strong{display:block;color:#405777;font-size:12px}.ocf-step small{display:block;margin-top:2px;font-size:10px;line-height:1.3}.ocf-step.is-active{background:#fff}.ocf-step.is-active:after{content:'';position:absolute;left:0;right:0;bottom:-1px;height:3px;background:#f97316}.ocf-step.is-active .ocf-step__dot{background:#f97316;color:#fff}.ocf-step.is-active strong{color:#10264f}.ocf-step.is-complete .ocf-step__dot{background:#dff7ea;color:#087a48}
.ocf-panel{display:none;padding:28px 26px 25px}.ocf-panel.is-active{display:block}
.ocf-panel-intro{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:24px;padding-bottom:18px;border-bottom:1px solid #e8edf4}.ocf-panel-intro h3{margin:0;color:#10264f;font-size:20px}.ocf-panel-intro p{max-width:760px;margin:6px 0 0;color:#718097;font-size:12px;line-height:1.55}.ocf-panel-tag{padding:7px 10px;border-radius:999px;background:#eef4ff;color:#174b8f;font-size:10px;font-weight:850;white-space:nowrap}
.ocf-wizard-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 26px;border-top:1px solid #e2e9f2;background:#fbfcfe}.ocf-wizard-footer__status{color:#75849a;font-size:12px}.ocf-wizard-footer__buttons{display:flex;gap:10px}.ocf-wizard-footer .btn{min-height:46px;padding:0 18px}
.ocf-client{max-width:920px;margin:0 auto}.ocf-client .ocf-card__head{background:#fbfcfe}.ocf-client .ocf-body{padding-top:24px}.ocf-client-divider{height:1px;margin:25px 0;background:#e7edf5}
.ocf-form .shop-location-picker{padding:20px;border-radius:13px;background:#fbfdff}.ocf-form .location-title h3{font-size:16px}.ocf-form .location-title p{font-size:12px}.ocf-form .location-required{font-size:10px}.ocf-form .location-mode{padding:15px}.ocf-form .location-mode strong{font-size:13px}.ocf-form .location-mode span{font-size:11px}.ocf-form .location-status{font-size:12px}.ocf-form .location-summary-label{font-size:10px}.ocf-form .location-summary strong{font-size:13px}.ocf-form .location-summary p,.ocf-form .location-note{font-size:11px}
@media(max-width:950px){.ocf-steps{grid-template-columns:repeat(2,minmax(0,1fr))}.ocf-step:nth-child(2){border-right:0}.ocf-step:nth-child(-n+2){border-bottom:1px solid #e2e9f2}.ocf-grid--three{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:700px){.ocf-card__head{padding:19px}.ocf-card__head p{font-size:12px}.ocf-card__icon{width:42px;height:42px;flex-basis:42px}.ocf-badge{display:none}.ocf-body,.ocf-panel{padding:20px 17px}.ocf-grid,.ocf-grid--three,.ocf-choice-grid{grid-template-columns:1fr;gap:17px}.ocf-span-2{grid-column:auto}.ocf-phone{grid-template-columns:105px minmax(0,1fr)}.ocf-field input:not([type="radio"]):not([type="checkbox"]),.ocf-field select,.ocf-field textarea,.ocf-select-button{font-size:16px}.ocf-steps{display:flex;overflow:auto}.ocf-step{min-width:200px;border-bottom:0!important}.ocf-panel-intro{flex-direction:column}.ocf-panel-tag{display:none}.ocf-wizard-footer{position:sticky;bottom:0;z-index:30;padding:12px;background:rgba(255,255,255,.97);box-shadow:0 -8px 24px rgba(16,38,79,.08)}.ocf-wizard-footer__status{display:none}.ocf-wizard-footer__buttons{width:100%}.ocf-wizard-footer__buttons .btn{flex:1}.ocf-actions{position:sticky;bottom:0;z-index:30;margin-left:-17px;margin-right:-17px;margin-bottom:-20px;padding:12px 17px;background:rgba(255,255,255,.97);box-shadow:0 -8px 24px rgba(16,38,79,.08)}.ocf-actions__right{width:100%}.ocf-actions__right .btn{flex:1}.ocf-category-menu{position:fixed;left:12px;right:12px;top:50%;transform:translateY(-50%);max-width:460px;margin:auto}.ocf-category-options{max-height:52vh}}
